css:
.p11b-page { display: grid; grid-template-rows: auto 1fr; min-height: 100cqh; overflow-x: clip; }
.p11b-page > .deck, .p11b-page > .p11b-center { grid-row: 2; align-self: center; }
.p11b-top { display: grid; gap: var(--s-2); width: 100%; max-width: 56rem; margin-inline: auto; padding: var(--s-3) var(--s-3) 0; grid-row: 1; }
.p11b-top:empty { display: none; }
.p11b-strip { --p11b-strip-h: 9.5rem; }
.p11b-strip .deck { --card: max(var(--card-min), min(var(--card-max), calc(100cqw - 2rem), calc(100cqh - 2rem - var(--peek) - var(--s-3) - var(--controls-h) - var(--p11b-strip-h)))); }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) { .p11b-strip { --p11b-strip-h: 19.5rem; } }
@media (max-width: 21.25rem) { .p11b-strip { --p11b-strip-h: 29.5rem; } }
.p11b-scrolled .p11b-page { margin-top: -5.25rem; }
.p11b-e { --frame-w: var(--w2); }
.p11b-focus { border-color: var(--blue); outline: var(--w1) solid var(--blue); outline-offset: calc(var(--w1) * -2); }
.p11b-w { position: relative; display: inline-grid; }
.p11b-tipw { position: relative; display: inline-flex; }
.p11b-tip-up { position: absolute; z-index: 30; bottom: calc(100% + var(--s-1)); left: 50%; translate: -50% 0; width: max-content; max-width: min(17.5rem, 80vw); text-align: center; }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) {
  .p11b-tip-up.p11b-tip-start { left: 0; translate: 0 0; text-align: start; }
  .p11b-tip-up.p11b-tip-end { left: auto; right: 0; translate: 0 0; text-align: end; }
}
.p11b-tip-dn { position: absolute; z-index: 30; top: calc(100% + var(--s-1)); right: 0; width: max-content; max-width: min(17.5rem, 80vw); }
.btn .spinner, .banner .spinner { width: var(--icon-sm); height: var(--icon-sm); }
.p11b-tip-ask { position: absolute; z-index: 30; top: 100%; left: 0; width: max-content; max-width: min(17.5rem, 70vw); }

.deck-card__foot.p-solo > :first-child { justify-self: center; }
.p-state { display: flex; align-items: center; min-height: 1.5rem; margin-top: calc(var(--s-1) * -1); }
.p-ask { display: inline-grid; place-items: center; min-width: var(--hit); min-height: var(--hit); margin-inline-start: calc(var(--s-2) * -1); padding: 0; border: var(--w1) solid transparent; border-radius: var(--r); background: transparent; color: var(--ink); cursor: pointer; }
.p-dashring { width: 0.625rem; height: 0.625rem; border: 1.5px dashed var(--muted); border-radius: 50%; }
.p-state--ask { position: relative; }

.p11b-face { gap: var(--s-3); }
.p11b-win .deck-card__head { margin-top: 0; }
.p11b-body { flex: 1 1 auto; min-height: 0; overflow: auto; display: grid; gap: var(--s-4); align-content: start; font-size: var(--fs-small); line-height: var(--lh-small); padding-block: var(--s-1); border-bottom: var(--w1) solid var(--rule); }
.p11b-foot { flex: none; display: flex; gap: var(--s-2); justify-content: space-between; }
.p11b-foot > * { flex: 1 1 0; }
.p11b-foot--one { justify-content: center; }
.p11b-foot--one > * { flex: 0 1 auto; min-width: 9rem; }

.p11b-body { overflow: auto; display: flex; flex-direction: column; gap: var(--s-2); padding-block: 0; border-bottom: 0; }
.p11b-fixed { flex: none; display: grid; gap: var(--s-2); }
.p11b-fh { justify-content: flex-start; column-gap: var(--s-2); }
.p11b-name { min-height: var(--ctl-h); resize: none; field-sizing: content; padding-block: calc((var(--ctl-h) - var(--lh-body)) / 2 - var(--w1)); }
.p11b-list { flex: 1 1 auto; min-height: 3.5rem; overflow: auto; display: flex; flex-direction: column; gap: var(--s-1); padding-block: var(--s-1); border-block: var(--w1) solid var(--rule); }
.p11b-list > * { flex: none; }
.p11b-hint { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; column-gap: var(--s-2); width: 100%; min-height: var(--hit); padding: var(--s-1) var(--s-3); border: var(--w1) solid transparent; border-radius: var(--r); background: transparent; color: var(--ink); text-align: start; cursor: pointer; }
.p11b-hint__t { font-size: var(--fs-small); line-height: var(--lh-small); font-weight: var(--fw-bold); }
.p11b-hint__s { grid-column: 1; font-size: var(--fs-cap); line-height: var(--lh-cap); color: var(--muted); }
.p11b-hint[aria-selected="true"] { border: var(--w2) solid var(--blue); color: var(--blue); }
.p11b-hint[aria-selected="true"] .p11b-hint__s { color: var(--blue); }
.p11b-hint .ico { grid-column: 2; grid-row: 1 / span 2; }
.p11b-note { padding: var(--s-1) var(--s-3); font-size: var(--fs-cap); line-height: var(--lh-cap); color: var(--muted); }
.p11b-msg { flex: none; }
.p11b-hint-cloud { flex: none; }
.p11b-ufoot { flex-direction: column; }
.p11b-ufoot > * { flex: none; }
.p11b-foot .p11b-tipw { flex: 1 1 0; display: flex; }
.p11b-foot .p11b-tipw > .btn { flex: 1; }
.p11b-foot .btn .spinner { width: var(--icon-sm); height: var(--icon-sm); }
.p11b-hover { text-decoration: underline; text-underline-offset: 0.25em; }

@media (max-width: 21.25rem) {
  .composer { gap: var(--s-1); padding-inline: var(--s-1); }
  .composer .input { padding-inline: var(--s-1); }
  .composer .input::placeholder { font-size: var(--fs-small); }
}

.deck__stack:has(> .p11b-win) { width: min(var(--card-max), calc(100cqw - 2rem)); height: auto; }
.deck__stack:has(> .p11b-win) ~ .deck__controls { display: none; }
.p11b-win { position: relative; left: auto; bottom: auto; width: 100%; height: auto; min-height: var(--card-min); max-height: calc(100cqh - 2rem - var(--p11b-win-off, 0rem)); display: flex; flex-direction: column; }
.p11b-win .deck-card__face { position: relative; inset: auto; flex: 1 1 auto; min-height: 0; }
.p11b-win [class*="-body"], .p11b-win .deck-card__scroll { scrollbar-width: thin; scrollbar-color: var(--line) var(--white); }
.p11b-strip { --p11b-win-off: 9.5rem; }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) { .p11b-strip { --p11b-win-off: 19.5rem; } }
@media (max-width: 21.25rem) { .p11b-strip { --p11b-win-off: 29.5rem; } }
.p11b-strip.p11b-strip--b { --p11b-win-off: 5.5rem; }
@media (max-width: 21.25rem) { .p11b-strip.p11b-strip--b { --p11b-win-off: 8rem; } }

.p11b-foot:has(.p11b-tipw) { display: grid; grid-template-columns: 1fr 1fr; }
.p11b-foot .p11b-tipw { display: contents; }
.p11b-foot .p11b-tipw > .tip { position: static; translate: none; width: auto; max-width: none; grid-column: 1 / -1; grid-row: 2; text-align: start; }
.p11b-draft { flex: none; font-size: var(--fs-cap); line-height: var(--lh-cap); color: var(--muted); }
